plugins {
    alias(libs.plugins.android.library)
    alias(libs.plugins.kotlin.android)
    alias(libs.plugins.maven.publish)
    alias(libs.plugins.rust.gradle)
}

object Library {
    const val groupId = "com.acurast"
    const val artifactId = "acurast-p2p"
}

// Release tags are `v<version>`; other builds use the development version.
val libraryVersion = System.getenv("CI_COMMIT_TAG")?.removePrefix("v") ?: "0.1.0-SNAPSHOT"

// Kotlin bindings generated by uniffi from the Rust library.
val uniffiDir = layout.buildDirectory.dir("generated/uniffi")

android {
    namespace = "com.acurast.p2p"
    compileSdk = 35
    ndkVersion = "29.0.14206865"

    defaultConfig {
        minSdk = 26
        version = libraryVersion
    }

    buildTypes {
        release {
            isMinifyEnabled = false
        }
    }
    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_11
        targetCompatibility = JavaVersion.VERSION_11
    }
    kotlinOptions {
        jvmTarget = "11"
    }
    sourceSets["main"].java.srcDir(uniffiDir)
}

cargo {
    module = "../../acurast-p2p-ffi"
    libname = "acurast_p2p_ffi"
    targets = listOf("arm", "arm64")
    profile = "release"
    prebuiltToolchains = true
    // The linker wrapper is a Python script; macOS only has `python3`.
    pythonCommand = "python3"
    apiLevel = 29
    // The Cargo workspace's target/ is at the repo root.
    targetDirectory = "../../target"
}

publishing {
    publications {
        register<MavenPublication>("maven") {
            groupId = Library.groupId
            artifactId = Library.artifactId
            version = libraryVersion

            afterEvaluate {
                from(components["release"])
            }
        }
    }
    // The Maven registry of this GitLab project, from CI.
    val apiUrl = System.getenv("CI_API_V4_URL")
    val projectId = System.getenv("CI_PROJECT_ID")
    val jobToken = System.getenv("CI_JOB_TOKEN")
    if (apiUrl != null && projectId != null && jobToken != null) {
        repositories {
            maven {
                name = "GitLab"
                url = uri("$apiUrl/projects/$projectId/packages/maven")
                credentials(HttpHeaderCredentials::class) {
                    name = "Job-Token"
                    value = jobToken
                }
                authentication {
                    create<HttpHeaderAuthentication>("header")
                }
            }
        }
    }
}

dependencies {
    compileOnly(libs.jna)
    implementation(libs.kotlinx.coroutines.core)
}

val uniffiBindings = tasks.register<Exec>("uniffiBindings") {
    dependsOn("cargoBuild")
    workingDir("../../acurast-p2p-ffi")
    commandLine(
        "cargo", "run", "--release",
        "--features", "uniffi/cli",
        "--bin", "uniffi-bindgen",
        "--", "generate",
        "--library", "../target/aarch64-linux-android/release/libacurast_p2p_ffi.so",
        "--language", "kotlin",
        "--no-format",
        "--out-dir", uniffiDir.get().asFile.absolutePath,
    )
}

tasks.configureEach {
    if (name == "mergeDebugJniLibFolders" || name == "mergeReleaseJniLibFolders") {
        dependsOn("cargoBuild")
        // The rust plugin's jniLibs dir is merged but not tracked, so a rebuilt .so would be skipped.
        inputs.dir(layout.buildDirectory.dir("rustJniLibs/android")).withPropertyName("rustJniLibs")
    }
}

tasks.matching { it.name.startsWith("compile") && it.name.endsWith("Kotlin") }.configureEach {
    dependsOn(uniffiBindings)
}
